sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 liftColor;
uniform float liftAmt;
layout(color) uniform half4 gammaColor;
uniform float gammaAmt;
layout(color) uniform half4 gainColor;
uniform float gainAmt;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 lf = (float3(liftColor.rgb) - 0.5) * 0.5 * liftAmt;
    float3 gm = float3(1.0) + (float3(gammaColor.rgb) - 0.5) * 2.0 * gammaAmt;
    float3 gn = float3(1.0) + (float3(gainColor.rgb) - 0.5) * 2.0 * gainAmt;
    float3 o = s * gn + lf * (1.0 - s);
    o = pow(max(o, float3(0.0)), float3(1.0) / max(gm, float3(0.1)));
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
